-- Oracle SQL Developer Database Export에서 생성한 제출용 DDL
-- 참조 순서에 맞춰 테이블을 배치하고 중복 제약조건과 저장 영역 옵션을 제거함

CREATE TABLE "MANUFACTURER" (
  "MANUFACTURER_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "NAME" VARCHAR2(100 CHAR) NOT NULL ENABLE,
  "PHONE" VARCHAR2(30 CHAR) NOT NULL ENABLE,
  CONSTRAINT "CK_FI_MAN_NAME" CHECK (TRIM(name) IS NOT NULL) ENABLE,
  CONSTRAINT "CK_FI_MAN_PHONE" CHECK (TRIM(phone) IS NOT NULL) ENABLE,
  PRIMARY KEY ("MANUFACTURER_ID") ENABLE
);

CREATE TABLE "MEMBER" (
  "MEMBER_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "NAME" VARCHAR2(50 CHAR) NOT NULL ENABLE,
  "EMAIL" VARCHAR2(254 CHAR) NOT NULL ENABLE,
  CONSTRAINT "CK_FI_MEM_NAME" CHECK (TRIM(name) IS NOT NULL) ENABLE,
  CONSTRAINT "CK_FI_MEM_EMAIL" CHECK (TRIM(email) IS NOT NULL) ENABLE,
  PRIMARY KEY ("MEMBER_ID") ENABLE
);

CREATE TABLE "PRODUCT" (
  "PRODUCT_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "NAME" VARCHAR2(150 CHAR) NOT NULL ENABLE,
  "PRICE" NUMBER(12,0) NOT NULL ENABLE,
  "MANUFACTURER_ID" NUMBER(10,0) NOT NULL ENABLE,
  CONSTRAINT "CK_FI_PRD_NAME" CHECK (TRIM(name) IS NOT NULL) ENABLE,
  CONSTRAINT "CK_FI_PRD_PRICE" CHECK (price >= 0) ENABLE,
  PRIMARY KEY ("PRODUCT_ID") ENABLE,
  CONSTRAINT "FK_FI_PRD_MAN" FOREIGN KEY ("MANUFACTURER_ID")
      REFERENCES "MANUFACTURER" ("MANUFACTURER_ID") ENABLE
);

CREATE TABLE "PRODUCT_OPTION" (
  "OPTION_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "PRODUCT_ID" NUMBER(10,0) NOT NULL ENABLE,
  "COLOR" VARCHAR2(30 CHAR) NOT NULL ENABLE,
  "OPTION_SIZE" VARCHAR2(20 CHAR) NOT NULL ENABLE,
  "STOCK_QUANTITY" NUMBER(10,0) DEFAULT 0 NOT NULL ENABLE,
  CONSTRAINT "CK_FI_OPT_COLOR" CHECK (TRIM(color) IS NOT NULL) ENABLE,
  CONSTRAINT "CK_FI_OPT_SIZE" CHECK (TRIM(option_size) IS NOT NULL) ENABLE,
  CONSTRAINT "CK_FI_OPT_STOCK" CHECK (stock_quantity >= 0) ENABLE,
  PRIMARY KEY ("OPTION_ID") ENABLE,
  CONSTRAINT "UQ_FI_OPT_VARIANT" UNIQUE ("PRODUCT_ID", "COLOR", "OPTION_SIZE") ENABLE,
  CONSTRAINT "FK_FI_OPT_PRODUCT" FOREIGN KEY ("PRODUCT_ID")
      REFERENCES "PRODUCT" ("PRODUCT_ID") ENABLE
);

CREATE TABLE "SALES_ORDER" (
  "ORDER_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "MEMBER_ID" NUMBER(10,0) NOT NULL ENABLE,
  "ORDERED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
  PRIMARY KEY ("ORDER_ID") ENABLE,
  CONSTRAINT "FK_FI_ORD_MEMBER" FOREIGN KEY ("MEMBER_ID")
      REFERENCES "MEMBER" ("MEMBER_ID") ENABLE
);

CREATE TABLE "ORDER_ITEM" (
  "ORDER_ITEM_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "ORDER_ID" NUMBER(10,0) NOT NULL ENABLE,
  "OPTION_ID" NUMBER(10,0) NOT NULL ENABLE,
  "QUANTITY" NUMBER(10,0) NOT NULL ENABLE,
  "UNIT_PRICE" NUMBER(12,0) NOT NULL ENABLE,
  CONSTRAINT "CK_FI_ITEM_QTY" CHECK (quantity >= 1) ENABLE,
  CONSTRAINT "CK_FI_ITEM_PRICE" CHECK (unit_price >= 0) ENABLE,
  PRIMARY KEY ("ORDER_ITEM_ID") ENABLE,
  CONSTRAINT "UQ_FI_ORDER_OPTION" UNIQUE ("ORDER_ID", "OPTION_ID") ENABLE,
  CONSTRAINT "FK_FI_ITEM_ORD" FOREIGN KEY ("ORDER_ID")
      REFERENCES "SALES_ORDER" ("ORDER_ID") ENABLE,
  CONSTRAINT "FK_FI_ITEM_OPT" FOREIGN KEY ("OPTION_ID")
      REFERENCES "PRODUCT_OPTION" ("OPTION_ID") ENABLE
);

CREATE TABLE "STOCK_HISTORY" (
  "HISTORY_ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY
      (MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1000 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE) NOT NULL ENABLE,
  "OPTION_ID" NUMBER(10,0) NOT NULL ENABLE,
  "ORDER_ITEM_ID" NUMBER(10,0),
  "CHANGE_TYPE" VARCHAR2(3 CHAR) NOT NULL ENABLE,
  "CHANGE_QUANTITY" NUMBER(10,0) NOT NULL ENABLE,
  "CHANGED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL ENABLE,
  CONSTRAINT "CK_FI_HIST_QTY" CHECK (change_quantity >= 1) ENABLE,
  CONSTRAINT "CK_FI_HIST_TYPE" CHECK ( (change_type = 'IN' AND order_item_id IS NULL) OR
      (change_type = 'OUT' AND order_item_id IS NOT NULL) ) ENABLE,
  PRIMARY KEY ("HISTORY_ID") ENABLE,
  CONSTRAINT "UQ_FI_HIST_ITEM" UNIQUE ("ORDER_ITEM_ID") ENABLE,
  CONSTRAINT "FK_FI_HIST_OPT" FOREIGN KEY ("OPTION_ID")
      REFERENCES "PRODUCT_OPTION" ("OPTION_ID") ENABLE,
  CONSTRAINT "FK_FI_HIST_ITEM" FOREIGN KEY ("ORDER_ITEM_ID")
      REFERENCES "ORDER_ITEM" ("ORDER_ITEM_ID") ENABLE
);
